async function rest(path,options={}){const b=base();if(!b)throw new Error('Supabase indisponível');const headers={...auth(),Accept:'application/json'};if(options.body!=null)headers['Content-Type']='application/json';if(options.prefer)headers.Prefer=options.prefer;const r=await fetch(`${b}/rest/v1/${path}`,{method:options.method||'GET',headers,body:options.body==null?undefined:(typeof options.body==='string'?options.body:JSON.stringify(options.body))});if(!r.ok)throw new Error(`Supabase ${r.status}: ${(await r.text()).slice(0,160)}`);if(r.status===204)return null;const text=await r.text();if(!text)return null;try{return JSON.parse(text)}catch{return text}}
