async function tmdb(path,params={}){const key=path+'?'+JSON.stringify(params);if(tmdbCache.has(key))return tmdbCache.get(key);const p=(async()=>{const u=new URL(`${base()}/functions/v1/tmdb-proxy`);u.searchParams.set('path',path);u.searchParams.set('language',localStorage.getItem('cinetracker_locale')==='en-US'?'en-US':'pt-BR');for(const[k,v]of Object.entries(params))if(v!=null&&v!=='')u.searchParams.set(k,String(v));const r=await Promise.race([fetch(u,{headers:auth()}),new Promise((_,rej)=>setTimeout(()=>rej(new Error('TMDB timeout')),9000))]);if(!r.ok)throw new Error(`TMDB ${r.status}`);return r.json()})();tmdbCache.set(key,p);try{const v=await p;tmdbCache.set(key,v);return v}catch(e){tmdbCache.delete(key);throw e}}
async function mapLimit(rows,limit,fn){const out=new Array(rows.length);let next=0;async function worker(){for(;;){const i=next++;if(i>=rows.length)return;try{out[i]=await fn(rows[i],i)}catch{out[i]=rows[i]}}}await Promise.all(Array.from({length:Math.min(limit,rows.length||1)},worker));return out}
function unwrap(v){let x=v;if(typeof x==='string'){try{x=JSON.parse(x)}catch{}}if(x&&typeof x==='object'&&'data'in x&&x.data!=null)x=x.data;if(Array.isArray(x)&&x.length===1&&x[0]&&typeof x[0]==='object'&&!('media_id'in x[0]))x=x[0];return x}
function mediaType(x){return x?.media_type==='movie'?'movie':'tv'}
function mediaId(x){return Number(x?.media_id||x?.id||0)||0}
function tmdbId(x){return Number(x?.tmdb_id||x?.raw_tmdb?.source_tmdb_id||x?.raw_tmdb?.id||0)||0}
function titleOf(x){return x?.title||x?.name||x?.media_title||x?.raw_tmdb?.title||x?.raw_tmdb?.name||x?.original_title||x?.original_name||'Sem título'}
