function isAnime(x){const raw=x?.raw_tmdb||x||{},g=(raw.genre_ids||raw.genres?.map(y=>y.id)||[]).map(Number),c=raw.origin_country||[];return g.includes(16)&&c.includes('JP')}
function dateKey(v){return String(v||'').slice(0,10)}
function ymd(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function shiftDay(n){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+n);return ymd(d)}
function common(title,subtitle){return `<div class="ct133-search-wrap"><span class="ct133-search-icon">⌕</span><input class="ct133-search" data-ct133-global-search type="search" placeholder="Buscar filmes, séries e atores…" autocomplete="off"><div class="ct133-search-results" data-ct133-search-results hidden></div></div><div class="ct133-title"><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>`}
