function cleanBaseTitle(t){return String(t||'').replace(/\s*\((?:18|19|20)\d{2}\)\s*$/,'').replace(/\s*\((US|USA|UK|GB|AU|CA)\)\s*$/i,'').trim()}
function titleHints(t,row){const s=String(t||''),ym=s.match(/\(((?:18|19|20)\d{2})\)\s*$/),cm=s.match(/\((US|USA|UK|GB|AU|CA)\)\s*$/i);return{base:cleanBaseTitle(s),year:Number(ym?.[1]||row?.release_year||0)||0,country:(cm?.[1]||'').toUpperCase().replace('USA','US').replace('UK','GB')}}
