function releasedCount(detail){if(!detail)return 0;const last=detail.last_episode_to_air||null,status=String(detail.status||'');if(last&&Number(last.season_number)>0&&Number(last.episode_number)>0){const ls=Number(last.season_number),le=Number(last.episode_number);let n=0;for(const s of detail.seasons||[]){const sn=Number(s.season_number||0);if(sn<=0)continue;if(sn<ls)n+=Math.max(0,Number(s.episode_count||0));else if(sn===ls)n+=le}return Math.max(n,le)}if(['Ended','Canceled'].includes(status))return Math.max(0,Number(detail.number_of_episodes||0));return 0}
async function persistMedia(row,detail,id){const local=mediaId(row);if(!local||!detail)return;const body={tmdb_id:Number(id),poster_path:detail.poster_path||row.poster_path||null,release_year:Number(String(detail.first_air_date||detail.release_date||'').slice(0,4))||row.release_year||null,raw_tmdb:detail};if(mediaType(row)==='tv'){body.total_seasons=Number(detail.number_of_seasons||0)||null;body.total_episodes=Number(detail.number_of_episodes||0)||null;body.runtime_minutes=Number((detail.episode_run_time||[])[0]||0)||row.runtime_minutes||null}else body.runtime_minutes=Number(detail.runtime||0)||row.runtime_minutes||null;try{await rest(`media?id=eq.${local}`,{method:'PATCH',body,prefer:'return=minimal'})}catch{}}
