function classifySeries(row){const seen=Math.max(0,Number(row.watched_episodes||0)),total=Math.max(0,Number(row.total_episodes||row.raw_tmdb?.number_of_episodes||0)),released=Math.max(0,Number(row.released_episodes||releasedCount(row.raw_tmdb)||0)),status=String(row._ctStatus||row.raw_tmdb?.status||''),missing=Math.max(0,released-seen),future=Math.max(0,total-released),last=Date.parse(row.last_watched_at||'')||0,age=last?(Date.now()-last)/86400000:9999;let bucket='';if(['Ended','Canceled'].includes(status)&&released>0&&seen>=released)bucket='completed';else if(seen===0&&row.is_watchlist)bucket='not_started';else if(seen>0&&released>0&&seen>=released)bucket='up_to_date';else if(seen>0&&missing>0)bucket=age>90?'dust':'continue';else if(row.is_up_to_date)bucket='up_to_date';else if(row.is_completed)bucket='completed';else if(seen>0||row.is_in_progress)bucket='continue';else if(row.is_watchlist)bucket='not_started';return{...row,watched_episodes:seen,total_episodes:total,released_episodes:released,_ctMissing:missing,_ctFuture:future,home_bucket:bucket||row.home_bucket||'not_started'}}
